// MsgServer is the server API for Msg service.
type MsgServer interface {
	// Identity change operations
	RequestIdentityChange(context.Context, *MsgRequestIdentityChange) (*MsgRequestIdentityChangeResponse, error)
	SubmitAssistantProof(context.Context, *MsgSubmitAssistantProof) (*MsgSubmitAssistantProofResponse, error)
	ApplyIdentityChange(context.Context, *MsgApplyIdentityChange) (*MsgApplyIdentityChangeResponse, error)
	RejectIdentityChange(context.Context, *MsgRejectIdentityChange) (*MsgRejectIdentityChangeResponse, error)
	SuspendIdentityChanges(context.Context, *MsgSuspendIdentityChanges) (*MsgSuspendIdentityChangesResponse, error)
	// Role management operations
	CreateRole(context.Context, *MsgCreateRole) (*MsgCreateRoleResponse, error)
	AssignRole(context.Context, *MsgAssignRole) (*MsgAssignRoleResponse, error)
	RevokeRole(context.Context, *MsgRevokeRole) (*MsgRevokeRoleResponse, error)
	// Multisig operations
	CreateMultisigWallet(context.Context, *MsgCreateMultisigWallet) (*MsgCreateMultisigWalletResponse, error)
	CreateMultisigProposal(context.Context, *MsgCreateMultisigProposal) (*MsgCreateMultisigProposalResponse, error)
	SignMultisigProposal(context.Context, *MsgSignMultisigProposal) (*MsgSignMultisigProposalResponse, error)
	ExecuteMultisigProposal(context.Context, *MsgExecuteMultisigProposal) (*MsgExecuteMultisigProposalResponse, error)
	// Time-locked operations
	ProposeTimeLockedAction(context.Context, *MsgProposeTimeLockedAction) (*MsgProposeTimeLockedActionResponse, error)
	ExecuteTimeLockedAction(context.Context, *MsgExecuteTimeLockedAction) (*MsgExecuteTimeLockedActionResponse, error)
	CancelTimeLockedAction(context.Context, *MsgCancelTimeLockedAction) (*MsgCancelTimeLockedActionResponse, error)
	// Emergency operations
	ActivateEmergencyAdmin(context.Context, *MsgActivateEmergencyAdmin) (*MsgActivateEmergencyAdminResponse, error)
	DeactivateEmergencyAdmin(context.Context, *MsgDeactivateEmergencyAdmin) (*MsgDeactivateEmergencyAdminResponse, error)
	// Validator operations
	RotateValidatorKey(context.Context, *MsgRotateValidatorKey) (*MsgRotateValidatorKeyResponse, error)
	// Session operations
	CreateSession(context.Context, *MsgCreateSession) (*MsgCreateSessionResponse, error)
	EndSession(context.Context, *MsgEndSession) (*MsgEndSessionResponse, error)
	// Admin operations
	UpdateParams(context.Context, *MsgUpdateParams) (*MsgUpdateParamsResponse, error)
	// GDPR operations
	EraseIdentity(context.Context, *MsgEraseIdentity) (*MsgEraseIdentityResponse, error)
	// DID key rotation operations
	RotateDIDKey(context.Context, *MsgRotateDIDKey) (*MsgRotateDIDKeyResponse, error)
}

